struct rds_connection *rds_conn_create(struct net *net, __be32 laddr,
                                      __be32 faddr,
                                      struct rds_transport *trans,
                                      gfp_t gfp, int is_outgoing)
{
    struct rds_connection *conn;

    /* Check for an existing connection */
    conn = rds_conn_find(laddr, faddr);
    if (conn)
        return conn;

    /* Allocate a new connection */
    conn = kzalloc(sizeof(*conn), gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    /* Initialize the connection */
    conn->laddr = laddr;
    conn->faddr = faddr;
    conn->transport = trans;
    conn->net = net;
    conn->is_outgoing = is_outgoing;

    spin_lock_init(&conn->spinlock);
    atomic_set(&conn->refcount, 1);
    INIT_LIST_HEAD(&conn->list);

    /* Handle loopback connections */
    if (laddr == faddr)
        conn->loopback = 1;

    /* Add connection to global data structure with locking */
    spin_lock(&rds_conn_table_lock);
    list_add(&conn->list, &rds_conn_table);
    spin_unlock(&rds_conn_table_lock);

    return conn;
}

struct rds_connection *rds_connection_get(struct net *net, __be32 laddr, __be32 faddr,
                                          struct rds_transport *trans, gfp_t gfp,
                                          int is_outgoing)
{
    struct rds_connection *conn;

    conn = rds_conn_lookup(net, laddr, faddr);
    if (conn)
        return conn;

    conn = kzalloc(sizeof(*conn), gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    conn->c_laddr = laddr;
    conn->c_faddr = faddr;
    conn->c_transport = trans;
    conn->c_net = net;
    conn->c_is_outgoing = is_outgoing;

    if (is_outgoing) {
        rds_conn_setup(conn);
        rds_loopback(conn);
    }

    spin_lock(&rds_conn_table_lock);
    rds_conn_add(conn);
    spin_unlock(&rds_conn_table_lock);

    return conn;
}

struct rds_connection *rds_conn_create(struct net *net, __be32 laddr,
                                      __be32 faddr,
                                      struct rds_transport *trans, gfp_t gfp,
                                      int is_outgoing)
{
    struct rds_connection *conn;

    conn = rds_conn_find(laddr, faddr);
    if (conn)
        return conn;

    conn = kzalloc(sizeof(*conn), gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    conn->laddr = laddr;
    conn->faddr = faddr;
    conn->transport = trans;
    conn->is_outgoing = is_outgoing;

    rds_conn_init(conn);

    if (is_outgoing) {
        rds_conn_connect(conn);
    } else {
        rds_conn_add_to_list(conn);
        rds_conn_notify_new(conn);
    }

    return conn;
}

struct rds_connection *rds_conn_create_or_get(struct net *net, __be32 laddr, __be32 faddr,
                                              struct rds_transport *trans, gfp_t gfp,
                                              int is_outgoing)
{
    struct rds_connection *conn;

    conn = rds_conn_find(net, laddr, faddr);
    if (conn)
        return conn;

    conn = kzalloc(sizeof(*conn), gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    conn->net = net;
    conn->laddr = laddr;
    conn->faddr = faddr;
    conn->transport = trans;
    conn->is_outgoing = is_outgoing;

    if (is_outgoing) {
        if (laddr == faddr) {
            rds_conn_set_loopback(conn);
        }
    }

    spin_lock(&rds_conn_table_lock);
    if (rds_conn_find(net, laddr, faddr)) {
        spin_unlock(&rds_conn_table_lock);
        kfree(conn);
        return ERR_PTR(-EEXIST);
    }

    rds_conn_add(conn);
    spin_unlock(&rds_conn_table_lock);

    rds_transport_init(conn);

    return conn;
}

struct rds_connection *rds_conn_create_or_get(struct net *net, __be32 laddr, __be32 faddr,
                                              struct rds_transport *trans, gfp_t gfp,
                                              int is_outgoing)
{
    struct rds_connection *conn;

    conn = rds_conn_find(laddr, faddr);
    if (conn)
        return conn;

    conn = kzalloc(sizeof(*conn), gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    conn->net = net;
    conn->laddr = laddr;
    conn->faddr = faddr;
    conn->transport = trans;
    conn->is_outgoing = is_outgoing;

    if (is_outgoing) {
        if (!rds_loopback_allowed(laddr, faddr))
            goto free_conn;
    }

    spin_lock(&rds_connection_lock);
    if (rds_conn_find(laddr, faddr)) {
        spin_unlock(&rds_connection_lock);
        goto free_conn;
    }

    rds_conn_add(conn);
    spin_unlock(&rds_connection_lock);

    return conn;

free_conn:
    kfree(conn);
    return ERR_PTR(-EEXIST);
}
